def on_round_start(memory):
    memory["rounds_played"] = memory.get("rounds_played", 0) + 1


def solve(name, clue, memory):
    try:
        t = TEMPLATES.get(
            "".join(str(1 + sum(o < ch for o in clue)) for ch in clue))
        if t is None:
            return None
        return t.translate({48 + i: c for i, c in enumerate(clue)})
    except Exception:
        return None


def on_round_end(items, memory):
    memory["wrong"] = [[it.get("clue"), it.get("solution")]
                       for it in items if not it.get("score")][:8]
